import React, {useState} from 'react';
import Box from '@mui/material/Box';
import Slider from '@mui/material/Slider';

export default function RangeSlider({ startValue,  endValue, setRangeValue }) {
  const [value, setValue] = useState([startValue, 2100]);

  const handleChange = (event, newValue) => {
    // force second value to stay at 2100
    const updatedValue = [newValue[0], 2100];
    setValue(updatedValue);
    setRangeValue((prev) => ({
      ...prev,
      startValue: updatedValue[0],
      endValue: 2100,
    }));
  };

  return (
    <Box sx={{ width: 800 }}>
      <Slider
        aria-label="Start value slider"
        value={value}
        onChange={handleChange}
        min={900}
        max={2100}
        valueLabelDisplay="on"
        marks
        step={100}
        // hide the end value's label
        // valueLabelFormat={(val) => (val === 2100 ? "" : val)}
        // disable moving the second thumb
        disableSwap
      />
    </Box>
  );
}
