import React from 'react';
import RangeSlider from "./RangeSlider";
import DropDown from './DropDown';
import { Input } from '@mui/base/Input';


const ConfigurationItem = ({
            parameterName,
            description,
            startingAux,
            disabled,
            showSlider,
            showInput,
            showLogicValue,
            showDropDown,
            setAUXValue,
            setRangeValue,
            getRangeValue,
            setOneValue,
        }) => {

    const auxList = ["AUX1", "AUX2", "AUX3", "AUX4", "AUX5", "AUX6", "AUX7", "AUX8"];
    const camerasList = ["Digital Waveshare G",
                         "Analog RunCam Phoenix 2 SP",
                         "Analog Foxeer Micro Cat 3",
                         "Analog RunCam Phoenix 2 SE v2",
                         "Analog Foxeer Mini Cat 3",
                         "Analog iFlight RaceCam R1 Mini"
    ];
    const logicValues = ["false", "true"];


    return (
        <>
            <div className="configuration-item">
                <div className="parameter">
                    {parameterName}
                    <div className='parameter-description'>
                        {description}   
                    </div> 
                    {showSlider && <DropDown options={auxList} placeholder={startingAux} setAUXValue={setAUXValue}/>}
                </div>
                {showSlider && <RangeSlider startValue={getRangeValue["startValue"]} endValue={getRangeValue["endValue"]} setRangeValue={setRangeValue}/>}
                {showDropDown && <DropDown options={camerasList} placeholder="Analog RunCam Phoenix 2 SP" setOneValue={setOneValue}/>}
                {showInput && <Input disabled={disabled} onChange={(event) => {setOneValue(event.target.value)}}/>}
                {showLogicValue && <DropDown options={logicValues} placeholder="false" setOneValue={setOneValue}/>}
            </div>
        </>
    )
}

export default ConfigurationItem;