import React, {useState} from 'react';
import yaml from 'js-yaml';
import Header from './components/Header';
import ConfigurationItem from './components/ConfigurationItem';
import { checkDataForErrors, convertAUXToChannel } from './utils';
import "./main.css"

function App() {
  const [armValue, setArmValue] = useState({
    "aux": "AUX1", startValue: 1500, endValue: 2100
  });
  const [zoomValue, setZoomValue] = useState({
    "aux": "AUX3", startValue: 1500, endValue: 2100
  });
  const [selectTargetValue, setSelectTargetValue] = useState({
    "aux": "AUX7", startValue: 1300, endValue: 2100
  });
  const [automaticControlValue, setAutomaticControlValue] = useState({
    "aux": "AUX7", startValue: 1700, endValue: 2100
  });
  // const [cameraValue, setCameraValue] = useState("Analog RunCam Phoenix 2 SP");
  // const [cameraPitch, setCameraPitch] = useState(0);
  const [centeredZoom, setCenteredZoom] = useState(false);
  const [calibrationSteps, setCalibrationSteps] = useState(null);
  const [error, setError] = useState("");
  const [newCameraValue, setNewCameraValue] = useState("");

  const makeConfigAndDownload = (data) => {
    const yamlStr = yaml.dump(data);
    const base64Data = btoa(unescape(encodeURIComponent(yamlStr)));

    const blob = new Blob([base64Data], { type: 'text/yaml' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = 'drone-app-public.yaml.base64';
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
    URL.revokeObjectURL(url);
  }


  const handleMoveToNextCalibrationStep = (step) => {
    if (step === 0) {
      setCalibrationSteps(0);
    } else if (step === 1 && !newCameraValue) {
        alert("Введіть назву камери!");
    } else if (step === 1) {
      setCalibrationSteps(1);
      const data = {"camera_calibration": true };
      makeConfigAndDownload(data);
    } else if (step === 2) {
      setCalibrationSteps(2);
    }
  }

  const saveToYaml = () => {
    const errors = checkDataForErrors(armValue, automaticControlValue);
    if (errors) {
      setError(errors)
      return;
    }
    const data = {
      "drone-controller": {
        "fc-bridge": {
          "joysticks": {
            "roll": {
              "channel": 1
            },
            "pitch": {
              "channel": 2
            },
            "yaw": {
              "channel": 4
            },
            "throttle": {
              "channel": 3
            },
            "arm": {
              "channel": convertAUXToChannel(armValue['aux']),
              "threshold": armValue['startValue']
            },
            "automatic-control": {
              "channel": convertAUXToChannel(automaticControlValue['aux']),
              "threshold": automaticControlValue['startValue']
            },
            "select-target": {
              "channel": convertAUXToChannel(selectTargetValue['aux']),
              "threshold": selectTargetValue['startValue']
            },
            "zoom-toggle": {
              "channel": convertAUXToChannel(zoomValue['aux']),
              "threshold": zoomValue['startValue']
            },
          },
        }
      },
      // "camera": {
        // "camera_calibration": cameraValue,
        // "pitch": cameraPitch,
        // "type": cameraValue === "Digital Waveshare G" ? "digital" : "analog"
      // },
      "video-processing-pipeline": {
        "zoom": { "centered": centeredZoom }
      }
    }
    makeConfigAndDownload(data);
  }

  return (
    <div className="main-container">
      <Header/>
      <div className='main-section'>
        {calibrationSteps !== null ?
            <>
              <div className="calibration-container">
                {calibrationSteps === 0 &&
                    <div className="camera-choice-container">
                      <div>Введіть назву камери: </div>
                      <input value={newCameraValue} onChange={(event) => setNewCameraValue(event.target.value)}/>
                      <button onClick={() => handleMoveToNextCalibrationStep(1)}>Продовжити</button>
                    </div>
                }
                {calibrationSteps === 1 &&
                  <>
                    <div className="camera-choice-container">
                      Залийте на ключ конфіг, який щойно завантажився...
                      <button onClick={() => handleMoveToNextCalibrationStep(2)}>Продовжити</button>
                    </div>
                  </>
                }
                {calibrationSteps === 2 &&
                    <>
                      <div className="white-text">
                      * Підключіть борт з залитим конфігом <br/>
                      * На екрані ви маєте побачити текст "Калібрація"  <br/>
                      * Для проведення калібрації, Вам потрібно створити 5-7 фото шахової дошки з різних ракурсів <br/>
                      * Фото робиться за допомогою перемикання AUX 1.         <br/>
                      * Після закінчення калібрації Ви побачите повідомлення "Калібрація успішна!". <br/>
                      * Після цього, поверніться до конфігу та виберіть щойно додану камеру. <br/>
                      </div>

                      <img src="/checkboard.svg" alt="checkboard" width={1122} height={793} />
                    </>
                }
              </div>
            </> :
          <>
            <ConfigurationItem parameterName="ARM" showSlider={true}
                               setRangeValue={setArmValue}
                               setAUXValue={setArmValue}
                               getRangeValue={armValue}
                               startingAux="AUX1"/>

            <ConfigurationItem parameterName="ЗУМ" showSlider={true}
                               setRangeValue={setZoomValue}
                               setAUXValue={setZoomValue}
                               getRangeValue={zoomValue}
                               startingAux="AUX3"/>

            <ConfigurationItem parameterName="ВИБІР ЦІЛІ" showSlider={true}
                               setRangeValue={setSelectTargetValue}
                               setAUXValue={setSelectTargetValue}
                               getRangeValue={selectTargetValue}
                               startingAux="AUX7"/>

            <ConfigurationItem parameterName="АВТОМАТИЧНИЙ КОНТРОЛЬ" showSlider={true}
                               setRangeValue={setAutomaticControlValue}
                               setAUXValue={setAutomaticControlValue}
                               getRangeValue={automaticControlValue}
                               startingAux="AUX7"/>

            {/*<div style={{display: "flex", flexDirection: "column", gap: "16px"}}>*/}
            {/*  <ConfigurationItem parameterName="КАМЕРА" description="При використанні камери, якої немає у списку, зверніться до виробника, або скалібруйте камеру власноруч."*/}
            {/*                     showDropDown={true}*/}
            {/*                     setOneValue={setCameraValue}/>*/}
            {/*  /!*<button className='save-button small' onClick={() => handleMoveToNextCalibrationStep(0)}>Скалібрувати камеру</button>*!/*/}
            {/*</div>*/}

            {/*<ConfigurationItem parameterName="КУТ НАХИЛУ КАМЕРИ" disabled={true} showInput={true}*/}
            {/*                   setOneValue={setCameraPitch}*/}
            {/*                   description="При використанні кріплення KTYR - 0. Перед зміною даного параметру рекомендуємо порадитись з виробником." />*/}

            <ConfigurationItem parameterName="ЦЕНТРОВАНИЙ ЗУМ" setOneValue={setCenteredZoom}
                               showLogicValue={true}
                               description="Розміщення зуму на OSD (false - справа знизу, true - в центрі знизу)." />

            <button className='save-button' onClick={saveToYaml}>Зберегти</button>
          </>
        }
      </div>
      {error && alert(error)}
    </div>
  )
}

export default App;
