export const checkDataForErrors = (armValue, automaticControlValue) => {
    if (armValue['aux'] === automaticControlValue['aux']) {
      return "Arm AUX має відрізнятись від AUX автоматичного контролю!";
    }

    // if (cameraPitch < -20 || cameraPitch > 20) {
    //   return "Invalid value for pitch!"
    // }
    return "";
}

export const convertAUXToChannel = (aux) => {
    return Number(aux.slice(-1)) + 4;
}

